import * as T from '../vendor/three.module.js';
// Original low-poly masonry models: white-stone wings, open vaulted halls,
// slate roofs, buttresses and forge fittings; no imported game assets.
export function bevelSlab(w=8,d=4.8,h=.35,bevel=.8){const x=w/2,z=d/2,b=bevel,s=new T.Shape();for(const [i,p]of [[-x+b,-z],[x-b,-z],[x,-z+b],[x,z-b],[x-b,z],[-x+b,z],[-x,z-b],[-x,-z+b]].entries())i?s.lineTo(...p):s.moveTo(...p);s.closePath();const g=new T.ExtrudeGeometry(s,{depth:h,bevelEnabled:false});g.rotateX(-Math.PI/2);g.translate(0,-h,0);return g;}
export function corbelGeometry(){const s=new T.Shape();s.moveTo(-4.8,0);s.lineTo(2.5,0);s.quadraticCurveTo(.5,-.8,-1.5,-2.2);s.quadraticCurveTo(-3.5,-3.1,-4.8,-5);s.closePath();const g=new T.ExtrudeGeometry(s,{depth:1.1,bevelEnabled:false,curveSegments:5});g.rotateY(Math.PI/2);g.translate(-.55,0,0);return g;}
export function citadelBuilding(kind,mats,team=0){
 const root=new T.Group(),solids=[],owned=[],geometries=[],effects=[],smoke=[],cloth=[],stone=mats.stone,trim=mats.edge,roof=team?mats.roofB:mats.roof;
 function box(x,y,z,w,h,d,m=stone,solid=true){const g=new T.BoxGeometry(w,h,d),o=new T.Mesh(g,m);geometries.push(g);o.position.set(x,y,z);root.add(o);if(solid)solids.push(o);return o;}
 function cylinder(x,y,z,r,h,m=stone,n=8){const g=new T.CylinderGeometry(r,r*1.15,h,n),o=new T.Mesh(g,m);geometries.push(g);o.position.set(x,y,z);root.add(o);return o;}
 const compact=kind==='supply';root.name=kind==='armory'?'Crown armory / forge':kind==='barracks'?'Recruitment hall':'Field supply shrine';root.userData.service={kind,entry:[0,0,compact?2.5:0],spawn:[0,0,0]};
 if(compact){box(0,.15,0,3.6,.3,3.6,trim);for(const x of [-1.3,1.3])box(x,1.4,-.5,.2,2.8,.2,mats.bark);for(const side of [-1,1]){const r=box(side*.9,2.7,-.5,2,.18,3.3,roof,false);r.rotation.z=-side*.22;}for(const x of [-.8,.8]){box(x,.55,0,1.1,.8,1.2,mats.bark);box(x,.55,.62,1.2,.12,.08,trim,false);}cylinder(0,1.2,-.8,.3,.5,trim);}
 else{
  // Wide central aisle remains genuinely open for recruitment and service access.
  for(const x of [-2,2]){for(const [z,d]of [[-1.825,1.85],[1.425,1.05]])box(x,1.7,z,1.25,3.4,d);box(x,3,-.0,1.25,.8,1.8);box(x,3.45,-.4,1.6,.3,5.1,trim);for(const z of [-2,1.4]){box(x+Math.sign(x)*.68,1.6,z,.3,3.2,.6,trim);box(x,2.1,z,.2,.8,.8,mats.dark,false);}}
  for(const x of [-1.8,1.8])box(x,1.8,-2.65,1.8,3.6,.45);box(0,3.4,-2.65,1.8,.4,.45);for(const x of [-1.2,1.2])box(x,1.6,1.8,.35,3.2,.55,trim);box(0,3.25,1.8,2.8,.4,.65,trim);
  for(const side of [-1,1]){const r=box(side*1.4,4.15,-.4,3.2,.3,6,roof,false);r.rotation.z=-side*.28;box(side*2.7,3.85,-.4,.18,.2,6.2,trim,false);}box(0,4.65,-.4,.3,.25,6.3,trim,false);
  cylinder(-2,4.1,-1.7,.8,2.2);for(let i=0;i<6;i++){const a=i*Math.PI/3;box(-2+Math.cos(a)*.7,5.25,-1.7+Math.sin(a)*.7,.35,.55,.35,trim,false);}box(-2,6.2,-1.7,.1,1.9,.1,mats.dark,false);cloth.push(box(-1.45,6.45,-1.7,1,.7,.08,roof,false));for(const side of [-1,1]){const arch=box(side*.65,3.5,2.45,.2,1.8,.35,trim,false);arch.rotation.z=side*.68;}box(0,4.12,2.45,.35,.4,.5,trim,false);
  if(kind==='armory'){box(2,2.8,-1.6,.8,4.8,.9);const haze=new T.MeshBasicMaterial({color:0x91a2a8,transparent:true,opacity:.22,depthWrite:false});owned.push(haze);for(let i=0;i<5;i++){const puff=new T.Mesh(new T.IcosahedronGeometry(.22,0),haze);geometries.push(puff.geometry);root.add(puff);smoke.push(puff);}box(1.85,.65,1.65,1.1,1.1,1.4,mats.dark);const glow=new T.MeshBasicMaterial({color:0xffb653});owned.push(glow);for(let i=0;i<4;i++){const flame=new T.Mesh(new T.OctahedronGeometry(.17,0),glow);geometries.push(flame.geometry);flame.position.set(1.7+i%2*.3,1.1,1.65+i*.13);root.add(flame);effects.push(flame);}for(const x of [-2.3,-1.8]){box(x,1,2,.12,1.8,.1,mats.dark,false);box(x,1.1,2,.65,.12,.1,trim,false);}}
  else{for(const x of [-2,2]){cylinder(x,1.2,2.1,.55,.13,mats.dark).rotation.x=Math.PI/2;box(x,1.3,2.1,.15,1.2,.12,trim,false);}box(0,2.8,2.15,1.3,.7,.1,roof,false);for(const x of [-.35,.35])box(x,2.8,2.22,.12,.45,.05,trim,false);}
 }
 root.userData.modelKind=kind;
 return {root,solids,update(t){smoke.forEach((o,i)=>{const phase=(t*.35+i/5)%1;o.position.set(2+Math.sin(t+i)*.16,5.2+phase*2,-1.6);o.scale.setScalar(.7+phase*1.4);});cloth.forEach(o=>o.rotation.y=Math.sin(t*3)*.15);effects.forEach((o,i)=>{o.scale.setScalar(.8+.2*Math.sin(t*9+i));o.rotation.y=t*2;});},dispose(){geometries.forEach(g=>g.dispose());owned.forEach(m=>m.dispose());}};
}
// Class props: held weapon at the billboard's right hand (the sprite costume carries headgear/off-hand).
// Geometry is shared per class at module level (userData.sharedGeometry, dispose is a no-op) so swapping
// or disposing an actor's prop never frees GPU buffers other actors still use.
const PROP_GEOMETRY=new Map(),PROP_ACCENT=new WeakMap(),TEAM_ACCENT=[0x80eee2,0xf49bc7],NEUTRAL_ACCENT=0xe9c46a;
function sharedGeometry(key,make){let g=PROP_GEOMETRY.get(key);if(!g){g=make();g.userData.sharedGeometry=true;g.dispose=()=>{};PROP_GEOMETRY.set(key,g);}return g;}
function accentMaterials(mats,team){let byTeam=PROP_ACCENT.get(mats);if(!byTeam){byTeam=new Map();PROP_ACCENT.set(mats,byTeam);}const key=team===0||team===1?team:-1;let m=byTeam.get(key);if(!m){const hex=key<0?NEUTRAL_ACCENT:TEAM_ACCENT[key],base=mats.edge,trim=base.clone();trim.color.set(hex).convertSRGBToLinear();if(base.onBeforeCompile)trim.onBeforeCompile=base.onBeforeCompile;if(base.customProgramCacheKey)trim.customProgramCacheKey=base.customProgramCacheKey;const glow=new T.MeshBasicMaterial({color:hex});m={trim,glow};byTeam.set(key,m);}return m;}
export function professionProp(classId,mats,team){const g=new T.Group(),{trim,glow}=accentMaterials(mats,team),wood=mats.bark||mats.edge,iron=mats.dark||mats.edge,bright=mats.edge,add=(key,make,m,x,y,z=0)=>{const o=new T.Mesh(sharedGeometry(classId+':'+key,make),m);o.position.set(x,y,z);g.add(o);return o;};
 if(classId==='fighter'){add('blade',()=>{const s=new T.Shape();s.moveTo(-.08,0);s.lineTo(.08,0);s.lineTo(.08,1.08);s.lineTo(0,1.3);s.lineTo(-.08,1.08);s.closePath();const geo=new T.ExtrudeGeometry(s,{depth:.06,bevelEnabled:false});geo.translate(0,0,-.03);return geo;},bright,.5,.62);add('guard',()=>new T.BoxGeometry(.56,.11,.16),trim,.5,.58);add('grip',()=>new T.CylinderGeometry(.05,.05,.3,6),wood,.5,.4);add('pommel',()=>new T.OctahedronGeometry(.09,0),trim,.5,.22);}
 else if(classId==='mage'){add('staff',()=>new T.CylinderGeometry(.055,.075,2.05,6),wood,.52,1.02);add('crook',()=>new T.TorusGeometry(.24,.05,4,10),trim,.52,2.2);add('orb',()=>new T.IcosahedronGeometry(.17,0),glow,.52,2.2);add('collar',()=>new T.CylinderGeometry(.1,.07,.16,6),trim,.52,1.96);}
 else if(classId==='builder'){add('handle',()=>new T.BoxGeometry(.1,1.05,.1),wood,.5,.78);add('head',()=>new T.BoxGeometry(.62,.3,.3),iron,.5,1.36);add('band',()=>new T.BoxGeometry(.14,.34,.34),trim,.5,1.36);add('claw',()=>new T.ConeGeometry(.12,.26,4),iron,.1,1.38).rotation.z=Math.PI/2;}
 else{add('bow',()=>new T.TorusGeometry(.72,.065,4,14,Math.PI*.92),wood,.36,1.02).rotation.z=-Math.PI*.46;add('string',()=>new T.BoxGeometry(.025,1.42,.025),bright,.42,1.02);add('wrap',()=>new T.BoxGeometry(.16,.24,.16),trim,1.08,1.02);for(const y of [.35,1.69])add('tip',()=>new T.OctahedronGeometry(.07,0),trim,.42,y);}
 g.userData.classId=classId;g.userData.team=team;return g;}
